#include<iostream>
#include<string>
#include<vector>
#include<queue>
using namespace std;
int dx[] = {-1,0,1,0};
int dy[] = {0,1,0,-1};
int N;
vector<string> mat;
vector<string> mat2;
vector<vector<int> >v1;
void ff(int x,int y,vector<vector<int> >& v)
{
	queue<int> q;
	q.push(x*N+y);
	while(q.size())
	{
		x = q.front()/N;
		y = q.front()%N;
		q.pop();
		for(int i=0;i<4;i++)
		{
			int nx = x+dx[i];
			int ny = y+dy[i];
			if(nx<0 || nx>=N ||ny<0 || ny>=N || v[nx][ny]!=-1 || mat[nx][ny]=='Y')
				continue;
			if(isdigit(mat2[nx][ny]) && mat2[nx][ny]!='0' && (v[x][y]+1<= v1[nx][ny]||v1[nx][ny]==-1) )
			{
				v[nx][ny] = v[x][y]+1;
				if(v[nx][ny]!=v1[nx][ny])
					q.push(nx*N+ny);
			}
			else if(v1[nx][ny]==-1 || v1[nx][ny]> v[x][y]+1)
			{
				v[nx][ny] = v[x][y]+1;
				q.push(nx*N+ny);
			}
		}
	}
}
void ini(int x,int y,vector<vector<int> >&v)
{
	v.clear();
	v.resize(N,vector<int>(N,-1));
	v[x][y] = 0;
	ff(x,y,v);
}
void get(vector<string> m,vector< vector<vector<int> > >& v)
{
	v.resize(N*N);
	int i,j;
	for(i=0;i<N;i++)
		for(j=0;j<N;j++)
			if(isdigit( m[i][j]) &&m[i][j]!='0' )
				ini(i,j,v[i*N+j]);
}

int maxN = 110;
const int INF = 1000000000;


struct node{ 
	int from,to,cost,flow;
	node(int _from,int _to,int _cost,int _flow):
	from(_from),to(_to),cost(_cost),flow(_flow){}
};

struct MinCostMaxFlow{
	int Nodes;
	vector<int> cost,flow,p;
	vector<node> edges;
	int tot_cost,tot_flow;
	pair<int,int> get_pair()
	{
		return make_pair( tot_cost , tot_flow );
	}
	int get_flow()
	{
		return tot_flow;
	}
	int get_cost()
	{
		return tot_cost;
	}
	void clear(int n)
	{
		maxN = Nodes = n;
		cost.clear();
		cost.resize(n,INF);
		flow.clear();
		flow.resize(n,0);
		p.clear();
		p.resize(n);
	}
	void add_edge(int from,int to,int cost,int flow)
	{
		edges.push_back( node(from,to,cost,flow) );
		edges.push_back( node(to,from,-cost,0) );
	}
	void get_path(int src,int sink)
	{
		clear(maxN);
		flow[src] = INF;
		cost[src] = 0;
		int i,j,f;
		for(i=0,f=1;i<Nodes && f ;i++)
			for(j=0,f=0;j<(int)edges.size();j++)
				if( edges[j].flow > 0 && cost[edges[j].to ] > cost[edges[j].from]+edges[j].cost)
				{
					f=1;
					cost[ edges[j].to ] = cost[edges[j].from]+edges[j].cost;
					flow[ edges[j].to ] = min( flow[ edges[j].from ] ,edges[j].flow );
					p[ edges[j].to ] = j;
				}

	}

	void cost_flow(int src,int sink)
	{
		if( src == sink ){ tot_cost = 0; tot_flow = INF; }
		tot_cost = 0;
		tot_flow = 0;
		while(true)
		{
			get_path( src , sink );
			if( flow[sink] == 0 ) break;

			for(int cur = sink; cur!=src ; cur = edges[ p[cur] ].from )
			{
				int rI = p[cur]%2 ? p[cur]-1 : p[cur]+1;
				edges[ p[cur] ].flow -= flow[sink];
				edges[ rI     ].flow += flow[sink];
				tot_cost += edges[ p[cur] ].cost*flow[sink];
			}
			tot_flow += flow[sink];
		}
	}
};
#define IN(a) (2*(a))
#define OUT(a) (2*(a)+1)
MinCostMaxFlow mcf;
void add_edge(int i,int j,int x,int y)
{
	int n1 = i*N+j;
	int n2 = x*N+y + N*N;
	mcf.add_edge(OUT(n1),IN(n2),0,1000000);
}
int main()
{
#ifndef ONLINE_JUDGE
	freopen("in.txt","rt",stdin);
#endif
	int n,t;
	cin>>n>>t;
	vector<string> a,b;
	N = n;
	a.resize(n);
	b.resize(n);
	int si,sj;
	for(int i=0;i<n;i++)
	{
		cin>>a[i];
		for(int j=0;j<n;j++)
			if(a[i][j] == 'Z')
			{
				si = i;
				sj = j;
			}
	}
	mat = a;
	for(int i=0;i<n;i++)
		cin>>b[i];
	mat2 = b;
	vector<vector<int> >v;
	vector<vector<vector<int> > >vv;
	v1 = vector<vector<int> >(N,vector<int>(N,1000000));
	ini(si,sj,v);
	v1 = v;
	get(a,vv);
	mcf.clear(4*N*N+2);
	int src = 4*N*N;
	for(int i=0;i<N*N;i++)
	{
		mcf.add_edge(src,IN(i),0,1000000);
		mcf.add_edge(OUT(N*N+i),src+1,0,1000000);
	}

	for(int x=0;x<N;x++)
		for(int y=0;y<N;y++)
		{
			if(isdigit(a[x][y]) )
			{
				int k = x*N+y;
				mcf.add_edge(IN(k),OUT(k),0,a[x][y]-'0');
			}
			if(isdigit(b[x][y]) )
			{
				int k = x*N+y + N*N;
				mcf.add_edge(IN(k),OUT(k),0,b[x][y]-'0');
			}

		}

		for(int i=0;i<N;i++)
			for(int j=0;j<N;j++)
				if(isdigit(b[i][j]) &&b[i][j]!='0')
				{
					for(unsigned int k=0;k<vv.size();k++)
					{
						if(vv[k].size())
						{
							int x = k/N;
							int y = k%N;
							//if(v[x][y]!=-1 && v[x][y]< vv[k][i][j] || vv[k][i][i]>t) continue;
							if(vv[k][i][j]==-1 || vv[k][i][j]>t) continue;
							add_edge(x,y,i,j);
						}
					}
				}
				mcf.cost_flow(src,src+1);

				cout<<mcf.get_flow()<<endl;
				return 0;
}
